function mediaFor(url){try{const u=new URL(url),host=u.hostname;if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return {};let youtube;if(['www.youtube.com','youtube.com','www.youtube-nocookie.com'].includes(host))youtube=u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|shorts)\/([^/]+)/)?.[1];if(host==='youtu.be')youtube=u.pathname.slice(1);if(youtube&&/^[a-zA-Z0-9_-]{11}$/.test(youtube))return {youtube};if(['vimeo.com','www.vimeo.com','player.vimeo.com'].includes(host)){const match=u.pathname.match(/^\/(?:video\/)?(\d+)(?:\/([a-zA-Z0-9]+))?\/?$/);if(match){const hash=u.searchParams.get('h')||match[2]||'';if(!hash||/^[a-zA-Z0-9]+$/.test(hash))return {vimeo:match[1],vimeoHash:hash};}}}catch{}return {};}
